    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store the separated groups
    separated_groups = []

    # Loop through the input string to identify and extract groups of nested parentheses
    start = 0
    stack = []
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                group = paren_string[start:i+1]
                # Check if each group is balanced
                if is_balanced(group):
                    # If balanced, add it to the list of separated groups
                    separated_groups.append(group)

    return separated_groups

def is_balanced(group: str) -> bool:
    stack = []
    for char in group:
        if char == '(':
            stack.append(char)
        elif char == ')':
